# A.Flow: 시세를 모은다. (네이버 금융 공개 시세, 로그인·키 필요 없음)
# 실행: pwsh -NoProfile -File "C:\Users\rawun\Desktop\주식시장\프로그램\시세수집.ps1"
# 결과: -OutDir (기본 프로그램\out) 에 snapshot.json · history.json · kospi.json · journal.json
#       Claude 아티팩트와 웹사이트(웹사이트\data)가 같은 파일을 쓴다. 일지는 -JournalPath 에서 가져온다.
#       시각은 PC나 서버가 어느 나라에 있든 한국 시간(KST)으로 적는다.
param(
  [string]$OutDir = (Join-Path $PSScriptRoot 'out'),
  [string]$JournalPath = (Join-Path $PSScriptRoot 'journal.json')
)
$ErrorActionPreference = 'Stop'
$ProgressPreference = 'SilentlyContinue'
$H = @{ 'User-Agent' = 'Mozilla/5.0'; 'Accept' = 'application/json' }
$dir = $PSScriptRoot
$KST = try { [TimeZoneInfo]::FindSystemTimeZoneById('Asia/Seoul') } catch { [TimeZoneInfo]::FindSystemTimeZoneById('Korea Standard Time') }
function Kst([datetime]$t) { [TimeZoneInfo]::ConvertTime($t.ToUniversalTime(), [TimeZoneInfo]::Utc, $KST) }
function KstNow { Kst ([datetime]::UtcNow) }

function Get-Json($url) { Invoke-RestMethod $url -Headers $H -TimeoutSec 20 }
function Num($v) { if ($null -eq $v -or "$v" -eq '') { return $null }; [double](("$v") -replace '[^\d.\-]', '') }
function Signed([double]$x, $dirName) {
  if ($dirName -eq 'FALLING' -and $x -gt 0) { return -$x }
  if ($dirName -eq 'RISING' -and $x -lt 0) { return -$x }
  return $x
}
function TimeText($t) { if ($t -is [datetime]) { (Kst $t).ToString('MM/dd HH:mm') } else { "$t" } }

$items = [System.Collections.Generic.List[object]]::new()
$errors = @()

# 1) 지수·선물 (현재값 + 일봉 60개)
$charts = @(
  @{ key = 'KOSPI'; name = '코스피'; group = '한국'; basic = 'https://m.stock.naver.com/api/index/KOSPI/basic'; chart = 'https://api.stock.naver.com/chart/domestic/index/KOSPI?periodType=dayCandle'; src = '네이버 금융' },
  @{ key = 'KOSDAQ'; name = '코스닥'; group = '한국'; basic = 'https://m.stock.naver.com/api/index/KOSDAQ/basic'; chart = 'https://api.stock.naver.com/chart/domestic/index/KOSDAQ?periodType=dayCandle'; src = '네이버 금융' },
  @{ key = 'K200F'; name = '코스피200 선물'; group = '한국'; basic = 'https://m.stock.naver.com/api/index/FUT/basic'; chart = 'https://api.stock.naver.com/chart/domestic/index/FUT?periodType=dayCandle'; src = '네이버 금융 (20분 지연, 주간 거래)' },
  @{ key = 'N225'; name = '닛케이225'; group = '일본'; basic = 'https://api.stock.naver.com/index/.N225/basic'; chart = 'https://api.stock.naver.com/chart/foreign/index/.N225?periodType=dayCandle'; src = '네이버 금융' },
  @{ key = 'SPX'; name = 'S&P 500'; group = '미국'; basic = 'https://api.stock.naver.com/index/.INX/basic'; chart = 'https://api.stock.naver.com/chart/foreign/index/.INX?periodType=dayCandle'; src = '네이버 금융' },
  @{ key = 'IXIC'; name = '나스닥'; group = '미국'; basic = 'https://api.stock.naver.com/index/.IXIC/basic'; chart = 'https://api.stock.naver.com/chart/foreign/index/.IXIC?periodType=dayCandle'; src = '네이버 금융' },
  @{ key = 'NQ'; name = '나스닥100 선물'; group = '미국'; basic = 'https://api.stock.naver.com/futures/NQcv1/basic'; chart = 'https://api.stock.naver.com/chart/foreign/futures/NQcv1?periodType=dayCandle'; src = '네이버 금융 (10분 지연)' }
)
foreach ($c in $charts) {
  try {
    $b = Get-Json $c.basic
    $ch = Get-Json $c.chart
    $dirName = $b.compareToPreviousPrice.name
    $items.Add([ordered]@{
        key = $c.key; name = $c.name; group = $c.group; unit = ''
        value = Num $b.closePrice
        chg = Signed (Num $b.compareToPreviousClosePrice) $dirName
        pct = Signed (Num $b.fluctuationsRatio) $dirName
        time = TimeText $b.localTradedAt; status = "$($b.marketStatus)"; src = $c.src
        spark = @($ch.priceInfos | Select-Object -Last 60 | ForEach-Object { [double]$_.closePrice })
        dates = @($ch.priceInfos | Select-Object -Last 60 | ForEach-Object { "$($_.localDate)" })
      })
  } catch { $errors += "$($c.name): $($_.Exception.Message)" }
}

# 2) 환율·금리·원자재 (최근 60일)
$mk = @(
  @{ key = 'USDKRW'; name = '원/달러 환율'; group = '금리·환율'; cat = 'exchange'; code = 'FX_USDKRW'; unit = '원'; src = '네이버 금융 (하나은행 고시)' },
  @{ key = 'US10Y'; name = '미 국채 10년'; group = '금리·환율'; cat = 'bond'; code = 'US10YT=RR'; unit = '%'; src = '네이버 금융' },
  @{ key = 'WTI'; name = 'WTI 유가'; group = '원자재'; cat = 'energy'; code = 'CLcv1'; unit = '$'; src = '네이버 금융 (10분 지연)' },
  @{ key = 'GOLD'; name = '국제 금'; group = '원자재'; cat = 'metals'; code = 'GCcv1'; unit = '$'; src = '네이버 금융 (10분 지연)' }
)
foreach ($m in $mk) {
  try {
    $rows = @((Get-Json "https://api.stock.naver.com/marketindex/$($m.cat)/$($m.code)/prices?page=1&pageSize=60") | ForEach-Object { $_ })
    $now = $rows[0]
    $dirName = $now.fluctuationsType.name
    $asc = [array]$rows; [array]::Reverse($asc)
    $items.Add([ordered]@{
        key = $m.key; name = $m.name; group = $m.group; unit = $m.unit
        value = Num $now.closePrice
        chg = Signed (Num $now.fluctuations) $dirName
        pct = Signed (Num $now.fluctuationsRatio) $dirName
        time = TimeText $now.localTradedAt; status = ''; src = $m.src
        spark = @($asc | ForEach-Object { Num $_.closePrice })
        dates = @($asc | ForEach-Object { if ($_.localTradedAt -is [datetime]) { (Kst $_.localTradedAt).ToString('yyyyMMdd') } else { ("$($_.localTradedAt)" -replace '\D', '').Substring(0, 8) } })
      })
  } catch { $errors += "$($m.name): $($_.Exception.Message)" }
}

# 3) 코스피 상세: 52주 고저, 수급, 상승/하락 종목 수, 2년 주봉
$kospi = $null
try {
  $ig = Get-Json 'https://m.stock.naver.com/api/index/KOSPI/integration'
  $tot = @{}; foreach ($t in $ig.totalInfos) { $tot[$t.code] = $t.value }
  $wk = Get-Json 'https://api.stock.naver.com/chart/domestic/index/KOSPI?periodType=weekCandle'
  $kospi = [ordered]@{
    high52 = Num $tot['highPriceOf52Weeks']; low52 = Num $tot['lowPriceOf52Weeks']
    tradingValue = Num $tot['accumulatedTradingValue']   # 백만원
    flow = [ordered]@{ date = "$($ig.dealTrendInfo.bizdate)"; personal = Num $ig.dealTrendInfo.personalValue; foreign = Num $ig.dealTrendInfo.foreignValue; institution = Num $ig.dealTrendInfo.institutionalValue }  # 억원
    breadth = [ordered]@{ up = [int](Num $ig.upDownStockInfo.riseCount) + [int](Num $ig.upDownStockInfo.upperCount); down = [int](Num $ig.upDownStockInfo.fallCount) + [int](Num $ig.upDownStockInfo.lowerCount); flat = [int](Num $ig.upDownStockInfo.steadyCount) }
    weeks = @($wk.priceInfos | ForEach-Object { , @("$($_.localDate)", [double]$_.closePrice) })
  }
} catch { $errors += "코스피 상세: $($_.Exception.Message)" }

# 3-2) 코스피 투자자별 순매수, 최근 2년 (억원, 하루 단위).
#      날짜마다 한 번씩 물어봐야 해서, 이미 받은 날은 OutDir\flows.json 에서 재사용하고 빠진 날과 최근 3일만 새로 받는다.
#      주말은 건너뛰고, 휴장일은 다른 날짜가 돌아오므로 버린다.
$flows = @()
try {
  $cache = @{}
  $old = Join-Path $OutDir 'flows.json'
  if (Test-Path $old) { foreach ($r in (Get-Content $old -Raw -Encoding utf8 | ConvertFrom-Json).rows) { $cache["$($r.date)"] = $r } }
  $today = (KstNow).Date
  $fresh = @(0..4 | ForEach-Object { $today.AddDays(-$_).ToString('yyyyMMdd') })   # 최근 며칠은 값이 바뀔 수 있어 다시 받는다
  $fetched = 0
  for ($d = $today.AddDays(-730); $d -le $today; $d = $d.AddDays(1)) {
    if ($d.DayOfWeek -in 'Saturday', 'Sunday') { continue }
    $ds = $d.ToString('yyyyMMdd')
    if ($cache.ContainsKey($ds) -and $ds -notin $fresh) {
      $c = $cache[$ds]
      if (-not ($c.personal -eq 0 -and $c.foreign -eq 0 -and $c.institution -eq 0)) { $flows += $c }
      continue
    }
    $t = Get-Json "https://m.stock.naver.com/api/index/KOSPI/trend?bizdate=$ds"
    $fetched++
    if ("$($t.bizdate)" -ne $ds) { continue }   # 휴장일
    $row = [pscustomobject][ordered]@{ date = $ds; personal = Num $t.personalValue; foreign = Num $t.foreignValue; institution = Num $t.institutionalValue }
    if ($row.personal -eq 0 -and $row.foreign -eq 0 -and $row.institution -eq 0) { continue }   # 휴장일은 셋 다 0 으로 온다
    $flows += $row
  }
  $flows = @($flows | Sort-Object date)
  "  투자자별 순매수: $($flows.Count)거래일 (새로 받은 날 $fetched)"
} catch { $errors += "투자자별 순매수: $($_.Exception.Message)" }

# 3-2b) 오늘 투자자별 순매수(억원): 코스피·코스닥·코스피200 선물
#       선물도 억원이다. 2026-10-14 외국인 +8,445 가 같은 날 기사의 '8,445억 원 순매수'와 일치함을 확인했다.
$investors = @()
foreach ($m in @(@{ key = 'KOSPI'; code = 'KOSPI'; unit = '억원' }, @{ key = 'KOSDAQ'; code = 'KOSDAQ'; unit = '억원' }, @{ key = 'K200F'; code = 'FUT'; unit = '억원' })) {
  try {
    $t = Get-Json "https://m.stock.naver.com/api/index/$($m.code)/trend"
    $investors += [ordered]@{ key = $m.key; date = "$($t.bizdate)"; unit = $m.unit; personal = Num $t.personalValue; foreign = Num $t.foreignValue; institution = Num $t.institutionalValue }
  } catch { $errors += "투자자별 매매($($m.key)): $($_.Exception.Message)" }
}

# 3-3) 코스피 시가총액 상위 10종목
$top = @()
try {
  $mv = Get-Json 'https://m.stock.naver.com/api/stocks/marketValue/KOSPI?page=1&pageSize=10'
  $rank = 0
  foreach ($s in $mv.stocks) {
    $rank++
    $dn = $s.compareToPreviousPrice.name
    $top += [ordered]@{
      rank = $rank; code = "$($s.itemCode)"; name = "$($s.stockName)"
      close = Num $s.closePrice; pct = Signed (Num $s.fluctuationsRatio) $dn
      mcap_jo = [math]::Round((Num $s.marketValue) / 10000, 1)          # 억원 → 조원
      value_eok = [math]::Round((Num $s.accumulatedTradingValue) / 100)  # 백만원 → 억원
      time = TimeText $s.localTradedAt
    }
  }
} catch { $errors += "시가총액 상위: $($_.Exception.Message)" }

# 4) 운영일지 (Claude 가 journal.json 에 적는다. 최근 30개만 싣는다)
$journal = @()
$jf = $JournalPath
if (Test-Path $jf) { $journal = @(Get-Content $jf -Raw -Encoding utf8 | ConvertFrom-Json | ForEach-Object { $_ }) }
$journal = @($journal | Sort-Object at -Descending | Select-Object -First 30)

# 5) 상황판(Claude 아티팩트 A.Flow)에 올릴 파일 4개: out\snapshot.json, history.json, kospi.json, journal.json
if ($errors.Count -gt 0 -and $items.Count -lt 5) { throw "수집 실패가 많아 파일을 만들지 않았습니다:`n$($errors -join "`n")" }
$out = $OutDir
New-Item -ItemType Directory -Force $out | Out-Null
$stamp = (KstNow).ToString('yyyy-MM-dd HH:mm')
$code = Get-Content $PSCommandPath -Raw -Encoding utf8
$meta = @(@{ label = '수집 시각 (KST)'; value = $stamp }, @{ label = '출처'; value = '네이버 금융 공개 시세 (api.stock.naver.com, m.stock.naver.com)' })
$metaCode = $meta + @(@{ label = '시세수집.ps1'; value = $code; type = 'code'; lang = 'powershell' })
function Save-Rows($name, $rows, [switch]$WithCode) {
  $doc = [ordered]@{ rows = @($rows); meta = $(if ($WithCode) { $metaCode } else { $meta }) }
  Set-Content (Join-Path $out "$name.json") ($doc | ConvertTo-Json -Depth 6 -Compress) -Encoding utf8
}

Save-Rows 'snapshot' ($items | ForEach-Object {
    [ordered]@{ key = $_.key; name = $_.name; group = $_.group; unit = $_.unit; value = $_.value; chg = $_.chg; pct = $_.pct; time = $_.time; src = $_.src }
  }) -WithCode
$hist = foreach ($it in $items) { for ($i = 0; $i -lt $it.spark.Count; $i++) { [ordered]@{ key = $it.key; date = $it.dates[$i]; close = $it.spark[$i] } } }
if ($kospi) { $hist = @($hist) + @($kospi.weeks | ForEach-Object { [ordered]@{ key = 'KOSPI_W'; date = $_[0]; close = $_[1] } }) }
Save-Rows 'history' $hist
if ($kospi) {
  Save-Rows 'kospi' @([ordered]@{
      date = $kospi.flow.date; high52 = $kospi.high52; low52 = $kospi.low52
      trading_value_eok = [math]::Round($kospi.tradingValue / 100)   # 백만원 → 억원
      flow_personal = $kospi.flow.personal; flow_foreign = $kospi.flow.foreign; flow_institution = $kospi.flow.institution
      up = $kospi.breadth.up; down = $kospi.breadth.down; flat = $kospi.breadth.flat
    })
}
Save-Rows 'journal' ($journal | ForEach-Object { [ordered]@{ at = $_.at; title = $_.title; text = $_.text } })
if ($flows.Count) { Save-Rows 'flows' $flows }
if ($top.Count) { Save-Rows 'top' $top }
if ($investors.Count) { Save-Rows 'investors' $investors }

"A.Flow 수집 완료: $($items.Count)개 지표, 수급 $($flows.Count)일, 상위 종목 $($top.Count)개, 오류 $($errors.Count)건 ($stamp)"
$errors | ForEach-Object { "  - $_" }
